 "content": "from collections import Counter, deque


def _components(grid, bg):
    h, w = len(grid), len(grid[0])
    seen = set()
    out = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg or (r, c) in seen:
                continue
            color = grid[r][c]
            q = deque([(r, c)])
            seen.add((r, c))
            pts = set()
            while q:
                y, x = q.popleft()
                pts.add((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    yy, xx = y + dy, x + dx
                    if 0 <= yy < h and 0 <= xx < w and (yy, xx) not in seen and grid[yy][xx] == color:
                        seen.add((yy, xx))
                        q.append((yy, xx))
            out.append((color, pts))
    return out


def _l_info(pts):
    """Return (elbow row/col, vertical direction, horizontal direction) for a thin L."""
    r0 = min(r for r, c in pts); r1 = max(r for r, c in pts)
    c0 = min(c for r, c in pts); c1 = max(c for r, c in pts)
    # The component must consist exactly of one full horizontal and one full vertical arm.
    for r in (r0, r1):
        for c in (c0, c1):
            expected = ({(r, x) for x in range(c0, c1 + 1)} |
                        {(y, c) for y in range(r0, r1 + 1)})
            if pts == expected and len(pts) >= 4:
                vd = 1 if r == r0 else -1
                hd = 1 if c == c0 else -1
                return r, c, vd, hd
    return None


def transform(grid):
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    comps = _components(grid, bg)
    markers = [(color, pts, _l_info(pts)) for color, pts in comps if _l_info(pts)]
    if not markers:
        return [row[:] for row in grid]
    # The marker is the largest thin L; other task objects can also have small L outlines.
    mc, mpts, info = max(markers, key=lambda item: len(item[1]))
    r, c, vd, hd = info
    candidates = []
    for color, pts in comps:
        if color == mc:
            continue
        # The indicated object lies opposite the horizontal arm, on the vertical-arm side.
        if any((y - r) * vd >= 0 and (x - c) * hd <= 0 for y, x in pts):
            # Use the nearest point in that sector; component size breaks ties deterministically.
            sector_pts = [(y, x) for y, x in pts if (y - r) * vd >= 0 and (x - c) * hd <= 0]
            if sector_pts:
                dist = min(abs(y - r) + abs(x - c) for y, x in sector_pts)
                candidates.append((dist, -len(pts), color, pts))
    if not candidates:
        return [row[:] for row in grid]
    target = min(candidates, key=lambda item: (item[0], item[1]))[3]
    out = [row[:] for row in grid]
    for y, x in target:
        out[y][x] = mc
    return out
